// Original CDI fixture mirrored from cdrom_image tests for the Flutter browser test root.
import 'dart:convert';
import 'dart:typed_data';

Uint8List cdiSessionsFixture() => _fixture(
    '',
    [(11, 5, 2352), (29, 5, 2048), (47, 4, 2336)]);

Uint8List _fixture(String descriptor, List<(int, int, int)> tracks) {
  final bytes = BytesBuilder(copy: false);
  for (final (seed, count, size) in tracks) {
    for (var sector = 0; sector < count; sector++) {
      bytes.add(Uint8List.fromList(
          List.generate(size, (i) => (seed + sector * 17 + i * 3) & 255)));
    }
  }
  bytes.add(base64Decode(descriptor));
  return bytes.takeBytes();
}
